.word-count-badge {
  display: inline-block;
  background: var(--bg-alt);
  color: var(--text-secondary);
  padding: 2px 8px;
  border-radius: 12px;
  font-size: 0.75rem;
  margin-left: 8px;
}

.word-count-badge::before {
  content: '📝 ';
}

js:
(function() {
  'use strict';

  const api = window.CardSpoke.utils;

  // Function to count words in text
  function countWords(text) {
    if (!text) return 0;
    return text.trim().split(/\s+/).filter(word => word.length > 0).length;
  }

  // Function to add word count badge
  function addWordCountBadge() {
    // Find card detail views
    const cardHeaders = document.querySelectorAll('.card-detail-header, .card-header');

    cardHeaders.forEach(header => {
      // Skip if already has badge
      if (header.querySelector('.word-count-badge')) return;

      // Find associated body
      const cardDetail = header.closest('.card-detail, .card');
      if (!cardDetail) return;

      const bodyEl = cardDetail.querySelector('.card-body, .card-detail-body');
      if (!bodyEl) return;

      const wordCount = countWords(bodyEl.textContent);

      const badge = document.createElement('span');
      badge.className = 'word-count-badge';
      badge.textContent = wordCount + ' words';

      header.appendChild(badge);
    });
  }

  // Run on page changes
  const observer = new MutationObserver(() => {
    setTimeout(addWordCountBadge, 100);
  });

  observer.observe(document.body, { childList: true, subtree: true });

  // Initial run
  addWordCountBadge();

  api.showToast('Word Count Plugin loaded!', 'success');
})();
